mapper.select:
SELECT DISTINCT ub.product_id FROM user_behavior ub WHERE ub.user_id IN
#{uid}
AND ub.product_id IS NOT NULL AND ub.product_id NOT IN ( SELECT product_id FROM user_behavior WHERE user_id = #{currentUserId} AND product_id IS NOT NULL ) GROUP BY ub.product_id ORDER BY SUM(CASE WHEN ub.behavior_type='purchase' THEN 8.0 WHEN ub.behavior_type='favorite' THEN 3.0 WHEN ub.behavior_type='cart' THEN 2.0 WHEN ub.behavior_type='search' THEN 2.0 WHEN ub.behavior_type='view' THEN 1.0 ELSE 0 END) DESC, COUNT(*) DESC LIMIT #{limit}

SELECT matched.category_id, matched.category_name, SUM(matched.weight) AS weight, SUM(matched.search_count) AS search_count FROM ( SELECT keyword_match.category_id, keyword_match.category_name, SUM(keyword_match.search_count * keyword_match.freshness_weight) * 2.0 AS weight, SUM(keyword_match.search_count) AS search_count FROM ( SELECT DISTINCT sh.id AS source_id, p.category_id, COALESCE(c.name, '未分类') AS category_name, sh.search_count, CASE WHEN sh.create_time >= DATE_SUB(NOW(), INTERVAL 7 DAY) THEN 1.8 WHEN sh.create_time >= DATE_SUB(NOW(), INTERVAL 30 DAY) THEN 1.0 ELSE 0.45 END AS freshness_weight FROM search_history sh JOIN product p ON p.deleted = 0 AND p.status = 1 LEFT JOIN category c ON c.id = p.category_id WHERE sh.user_id = #{userId} AND sh.keyword IS NOT NULL AND sh.keyword != '' AND p.category_id IS NOT NULL AND ( COALESCE(c.name, '') LIKE CONCAT('%', sh.keyword, '%') OR p.name LIKE CONCAT('%', sh.keyword, '%') OR COALESCE(p.description, '') LIKE CONCAT('%', sh.keyword, '%') OR COALESCE(CAST(p.tags AS CHAR), '') LIKE CONCAT('%', sh.keyword, '%') ) ) keyword_match GROUP BY keyword_match.category_id, keyword_match.category_name
UNION ALL
SELECT behavior_match.category_id, behavior_match.category_name, SUM(behavior_match.freshness_weight) * 2.0 AS weight, COUNT(*) AS search_count FROM ( SELECT DISTINCT ub.id AS source_id, p.category_id, COALESCE(c.name, '未分类') AS category_name, CASE WHEN ub.create_time >= DATE_SUB(NOW(), INTERVAL 7 DAY) THEN 1.8 WHEN ub.create_time >= DATE_SUB(NOW(), INTERVAL 30 DAY) THEN 1.0 ELSE 0.45 END AS freshness_weight FROM user_behavior ub JOIN product p ON p.deleted = 0 AND p.status = 1 LEFT JOIN category c ON c.id = p.category_id WHERE ub.user_id = #{userId} AND ub.behavior_type = 'search' AND ub.search_keyword IS NOT NULL AND ub.search_keyword != '' AND p.category_id IS NOT NULL AND ( COALESCE(c.name, '') LIKE CONCAT('%', ub.search_keyword, '%') OR p.name LIKE CONCAT('%', ub.search_keyword, '%') OR COALESCE(p.description, '') LIKE CONCAT('%', ub.search_keyword, '%') OR COALESCE(CAST(p.tags AS CHAR), '') LIKE CONCAT('%', ub.search_keyword, '%') ) ) behavior_match GROUP BY behavior_match.category_id, behavior_match.category_name ) matched GROUP BY matched.category_id, matched.category_name ORDER BY weight DESC, search_count DESC LIMIT #{limit}

SELECT ub2.product_id
FROM user_behavior ub1
JOIN user_behavior ub2 ON ub1.user_id = ub2.user_id AND ub2.product_id != #{productId}
WHERE ub1.product_id = #{productId}
  AND ub2.product_id IS NOT NULL
GROUP BY ub2.product_id
ORDER BY COUNT(DISTINCT ub2.user_id) DESC
LIMIT #{limit}
